"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"
import { rove } from "@/lib/0db/rove"

/** One point: its label and a number under each series key (`value` when there's one series). */
type ChartDatum = { label: string; value?: number; [key: string]: string | number | undefined }
/** A series: the key it reads from each datum, and its name in the readout. */
type ChartSeries = { key: string; label: string }

type ChartShared = Omit<React.ComponentProps<"figure">, "children"> & {
  data: ChartDatum[]
  /** Two or more series turn the one giant number into a short list, read at the point you're on. */
  series?: ChartSeries[]
  /** Names the chart for assistive tech, e.g. "Visits by month, 2026". */
  label: string
  /** What the values count, e.g. "visits". Reads "visits in September" beside the number. */
  unit?: string
  /** The point the number rests on; it carries the accent. Defaults to the last. */
  now?: number
  /** The value the tallest bar could reach. Defaults to the next round number above the largest. */
  max?: number
  format?: (value: number) => string
  /** Pins the pointed-at look on the point the number is on; set on the root for documentation. */
  "data-force"?: string
}

type ChartProps = ChartShared & {
  /**
   * stems: hairlines and dots against one very large number. spark: word-sized, set in a sentence,
   * the number after it. isotype: each month a column of dots, one dot a fixed amount, counted not scaled.
   */
  variant?: "stems" | "spark" | "isotype"
  /** isotype: what one dot counts. Defaults to a tenth of the ceiling. */
  each?: number
  /** stems: bars stand up from the baseline, or run along from the start edge as a ledger. */
  orientation?: "vertical" | "horizontal"
  /** stems with series: one stem per column, each series a length of it, a dot at every joint. */
  stacked?: boolean
}

/** What a chart's drawing layer is given: each point's [from, to] per series, 0–1 of the ceiling. */
type ChartGeometry = { spans: [number, number][][]; series: ChartSeries[] }

type ChartFrameProps = Omit<ChartProps, "variant"> & {
  variant: string
  /** Drawn in the plot under the points (line-chart, area-chart). */
  layer?: (geometry: ChartGeometry) => React.ReactNode
}

const figures = new Intl.NumberFormat("en-GB")

// ponytail: 1, 2, 2.5, 5, 10 steps; swap for d3-scale ticks if axes ever need more than a ceiling.
function ceiling(n: number) {
  if (n <= 0) return 1
  const p = 10 ** Math.floor(Math.log10(n))
  return ([1, 2, 2.5, 5, 10].find((s) => s * p >= n) ?? 10) * p
}

/**
 * The frame every 0dB chart shares: the rolling readout (one giant number, or a short list for
 * several series), a plot of one button per point, and the axis. Point at or focus a point and the
 * number rolls to it; Left and Right (or Up and Down) move between points, Home and End jump.
 */
function ChartFrame({
  data,
  series,
  label,
  unit,
  now = data.length - 1,
  max,
  format = figures.format,
  variant,
  each,
  orientation = "vertical",
  stacked = false,
  layer,
  className,
  style,
  ...props
}: ChartFrameProps) {
  const [shown, setShown] = React.useState(now)
  // Nothing counts itself in until the person has pointed at something.
  const [moved, setMoved] = React.useState(false)
  const target = React.useRef(now)
  const values = React.useRef<(HTMLSpanElement | null)[]>([])
  const plot = React.useRef<HTMLSpanElement>(null)
  const spark = variant === "spark"
  const isotype = variant === "isotype"
  // Spark and isotype read one series; stems, lines and areas read them all.
  const list = series?.length ? (spark || isotype ? series.slice(0, 1) : series) : [{ key: "value", label: unit ?? "" }]
  const multi = list.length > 1
  const stack = multi && stacked
  const across = orientation === "horizontal" && !spark && !isotype
  // ponytail: missing values count as 0; add gaps in the line when data with holes turns up.
  const raw = data.map((d) => {
    let from = 0
    return list.map((s): [number, number] => {
      const v = Number(d[s.key] ?? 0)
      const span: [number, number] = stack ? [from, from + v] : [0, v]
      from += v
      return span
    })
  })
  const tops = raw.map((s) => Math.max(...s.map((p) => p[1])))
  const top = max ?? ceiling(Math.max(...tops))
  const unitEach = each ?? top / 10
  const rows = isotype ? Math.max(1, Math.round(top / unitEach)) : 0
  const spans = raw.map((s) => s.map(([a, b]): [number, number] => [Math.min(a / top, 1), Math.min(b / top, 1)]))
  // A sparkline spans its own range, low to high, so a word-sized line still shows the shape.
  const lo = Math.min(...tops)
  const hi = Math.max(...tops)
  // What the readout shows at point i: one number, or each series then (stacked) the sum.
  const reading = (i: number) => (multi ? [...raw[i].map((p) => p[1] - p[0]), ...(stack ? [tops[i]] : [])] : [tops[i]])

  function show(i: number) {
    if (i === target.current) return
    const was = reading(target.current)
    const next = reading(i)
    target.current = i
    setMoved(true)
    let rolled = false
    values.current.forEach((el, k) => {
      if (!el || next[k] === was[k]) return
      rolled = true
      roll(el, () => setShown(target.current), "0.3em", next[k] > was[k] ? 1 : -1)
    })
    if (!rolled) setShown(i)
  }

  const at = data[shown] ?? data[now]
  const said = reading(shown)
  const words = unit ? `${unit} in ${at.label}` : at.label
  // A sparkline sits in a sentence, so it's phrasing content: spans, not a figure.
  const Root = (spark ? "span" : "figure") as "figure"
  const Read = (spark ? "span" : "figcaption") as "figcaption"
  const read = multi ? (
    <Read data-slot="chart-read" className="db-chart-read" data-list="">
      <span className="db-chart-at">{at.label}</span>
      <span className="db-chart-list">
        {said.map((v, k) => (
          <span key={k} className="db-chart-row" data-series={k < list.length ? k : undefined} data-total={k === list.length || undefined}>
            <span ref={(el) => void (values.current[k] = el)} className="db-chart-value">
              {format(v)}
            </span>
            <span className="db-chart-name">
              <i className="db-chart-swatch" aria-hidden="true" />
              {k < list.length ? list[k].label : unit ? `${unit} in all` : "in all"}
            </span>
          </span>
        ))}
      </span>
    </Read>
  ) : (
    <Read data-slot="chart-read" className="db-chart-read">
      <span ref={(el) => void (values.current[0] = el)} className="db-chart-value">
        {format(said[0])}
      </span>
      {spark ? " " : null}
      <span>{words}</span>
    </Read>
  )
  const Plot = (spark ? "span" : "div") as "span"

  return (
    <Root
      data-slot="chart"
      data-variant={variant}
      data-orientation={across ? "horizontal" : undefined}
      data-stacked={stack || undefined}
      data-moved={moved || undefined}
      className={cn("db-chart", className)}
      style={{ "--n": data.length, "--rows": rows, "--m": list.length, ...style } as React.CSSProperties}
      {...props}
    >
      {spark ? null : read}
      <Plot
        ref={plot}
        role="group"
        aria-label={label}
        data-slot="chart-plot"
        className="db-chart-plot"
        onKeyDown={(e) => rove(e, "[data-slot=chart-bar]")}
        onPointerLeave={() => plot.current && !plot.current.contains(document.activeElement) && show(now)}
        onBlur={(e) => !plot.current?.contains(e.relatedTarget) && show(now)}
      >
        {layer ? layer({ spans, series: list }) : null}
        {data.map((d, i) => {
          const on = tops[i] > 0 ? Math.min(rows, Math.max(1, Math.round(tops[i] / unitEach))) : 0
          const read = multi
            ? `${d.label}: ${list.map((s, k) => `${s.label} ${format(raw[i][k][1] - raw[i][k][0])}`).join(", ")}${stack ? `, ${format(tops[i])} in all` : ""}`
            : `${d.label}, ${format(tops[i])}${unit ? ` ${unit}` : ""}`
          return (
            <button
              key={d.label}
              type="button"
              tabIndex={i === shown ? 0 : -1}
              data-slot="chart-bar"
              className="db-chart-bar"
              style={{ "--v": Math.min(tops[i] / top, 1), "--s": hi > lo ? 0.2 + (0.8 * (tops[i] - lo)) / (hi - lo) : 1 } as React.CSSProperties}
              data-now={i === now || undefined}
              data-shown={i === shown || undefined}
              aria-label={read}
              onPointerEnter={() => show(i)}
              onFocus={() => show(i)}
            >
              {Array.from({ length: rows }, (_, k) => (
                <i key={k} data-on={k < on || undefined} data-top={k === on - 1 || undefined} style={{ "--k": k } as React.CSSProperties} />
              ))}
              {multi
                ? spans[i].map(([b, v], k) => (
                    <span
                      key={k}
                      className="db-chart-mark"
                      data-series={k}
                      data-top={k === list.length - 1 || undefined}
                      style={{ "--b": b, "--v": v, "--k": k } as React.CSSProperties}
                    />
                  ))
                : null}
            </button>
          )
        })}
      </Plot>
      {spark ? (
        <>
          {" "}
          {read}
        </>
      ) : (
        <div data-slot="chart-axis" className="db-chart-axis" aria-hidden="true">
          {data.map((d, i) => (
            <span key={d.label} data-shown={i === shown || undefined}>{across ? d.label : d.label.charAt(0)}</span>
          ))}
        </div>
      )}
      {isotype ? (
        <span data-slot="chart-key" className="db-chart-key">
          <i aria-hidden="true" />
          One dot, {format(unitEach)}
          {unit ? ` ${unit}` : ""}
        </span>
      ) : null}
    </Root>
  )
}

/**
 * Hairlines and dots against one very large number. Point at a bar, or focus it, and
 * its line inks, its dot swells and the number rolls to it; leave and it rolls back.
 * Every bar is a button labelled with its value, so the data is read without a pointer.
 */
function Chart({ variant = "stems", ...props }: ChartProps) {
  return <ChartFrame variant={variant} {...props} />
}

export { Chart, ChartFrame, type ChartProps, type ChartShared, type ChartDatum, type ChartSeries, type ChartGeometry }

@layer components {
  /* ── db-chart ── hairlines and dots, against one very large number */
  .db-chart { margin: 0; display: grid; gap: var(--db-space-5); }
  .db-chart:not([data-variant="spark"]) { container-type: inline-size; }
  .db-chart-read { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--db-space-4); color: var(--db-graphite); }
  /* The number is as large as the chart allows: SPECTRA's scale contrast, tiny data against giant type. */
  .db-chart-value { display: inline-block; font-size: clamp(var(--db-ff), 16cqi, var(--db-fff)); line-height: 0.9; letter-spacing: var(--db-ff-tr); font-weight: 200; color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums; }
  .db-chart-plot {
    display: grid; grid-template-columns: repeat(var(--n, 12), minmax(0, 1fr)); height: 13rem;
    background: repeating-linear-gradient(to top, var(--db-rule) 0 1px, transparent 1px 25%);
    box-shadow: inset 0 calc(-1 * var(--db-hairline)) 0 var(--db-ink);
  }
  .db-chart-bar { position: relative; appearance: none; border: 0; margin: 0; padding: 0; background: none; cursor: crosshair; }
  .db-chart-bar::before, .db-chart-bar::after { content: ""; position: absolute; left: 50%; pointer-events: none; }
  .db-chart-bar::before { bottom: 0; width: var(--db-hairline); height: calc(var(--v) * 100%); translate: -50% 0; background: var(--db-pencil); transition: width var(--db-allegro), background-color var(--db-allegro); }
  .db-chart-bar::after {
    bottom: calc(var(--v) * 100%); width: 7px; height: 7px; border-radius: 50%; translate: -50% 50%;
    background: var(--db-paper); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-pencil);
    transition: scale var(--db-moderato) var(--db-spiccato), background-color var(--db-allegro), box-shadow var(--db-allegro);
  }
  .db-chart-bar:is(:hover, :focus-visible)::before, .db-chart[data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown]::before { width: var(--db-stroke); background: var(--db-ink); }
  .db-chart-bar:is(:hover, :focus-visible)::after, .db-chart[data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown]::after { scale: 1.5; background: var(--db-ink); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-ink); }
  .db-chart-bar[data-now]::after { background: var(--db-accent); box-shadow: none; }
  .db-chart-bar:focus-visible { outline-offset: 2px; }
  .db-chart-axis { display: grid; grid-template-columns: repeat(var(--n, 12), minmax(0, 1fr)); margin-top: calc(-1 * var(--db-space-3)); font-size: var(--db-pp); color: var(--db-pencil); text-align: center; }

  /* spark: word-sized, set in the sentence (Tufte's sparkline). Stems as tall as a capital, standing
     on the baseline, the accent dot on now; the number follows at the text's own size and rolls. */
  .db-chart[data-variant="spark"] { display: inline; }
  .db-chart[data-variant="spark"] > .db-chart-plot {
    display: inline-flex; align-items: stretch; height: 0.72em; vertical-align: baseline;
    margin-inline: 0.1em 0.05em; background: none; box-shadow: none;
  }
  .db-chart[data-variant="spark"] .db-chart-bar { flex: none; width: 0.34em; cursor: crosshair; }
  .db-chart[data-variant="spark"] .db-chart-bar::before { height: calc(var(--s) * 100%); background: var(--db-graphite); }
  .db-chart[data-variant="spark"] .db-chart-bar::after { bottom: calc(var(--s) * 100%); width: 0.26em; height: 0.26em; background: transparent; box-shadow: none; }
  .db-chart[data-variant="spark"] .db-chart-bar[data-now]::after { background: var(--db-accent); }
  .db-chart[data-variant="spark"] .db-chart-bar:is(:hover, :focus-visible)::after,
  .db-chart[data-variant="spark"][data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown]::after { scale: 1; background: var(--db-ink); box-shadow: none; }
  .db-chart[data-variant="spark"] > .db-chart-read { display: inline; color: inherit; }
  .db-chart[data-variant="spark"] .db-chart-value { font-size: inherit; line-height: inherit; letter-spacing: inherit; font-weight: 500; }

  /* isotype: Neurath's rule, count don't scale. Each column a stack of dots, one dot a fixed amount:
     had in ink, the room left to the ceiling in hairline rings; now's top dot is the accent.
     Pointing a column sets the rest back and counts its dots up, one after another. */
  .db-chart[data-variant="isotype"] { --db-chart-dot: clamp(0.5rem, calc(55cqi / var(--n)), 1rem); }
  .db-chart[data-variant="isotype"] > .db-chart-plot { height: auto; background: none; box-shadow: none; }
  .db-chart[data-variant="isotype"] .db-chart-bar { display: flex; flex-direction: column-reverse; align-items: center; gap: calc(var(--db-chart-dot) * 0.45); padding-block: var(--db-space-2); }
  .db-chart[data-variant="isotype"] .db-chart-bar::before, .db-chart[data-variant="isotype"] .db-chart-bar::after { content: none; }
  .db-chart[data-variant="isotype"] .db-chart-bar > i {
    display: block; flex: none; inline-size: var(--db-chart-dot); aspect-ratio: 1; border-radius: 50%;
    box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong);
    transition: background-color var(--db-allegro), box-shadow var(--db-allegro);
  }
  .db-chart[data-variant="isotype"] .db-chart-bar > i[data-on] { background: var(--db-ink); box-shadow: none; }
  .db-chart[data-variant="isotype"] .db-chart-bar[data-now] > i[data-top] { background: var(--db-accent); }
  .db-chart[data-variant="isotype"] > .db-chart-plot:is(:hover, :focus-within) > .db-chart-bar:not([data-shown]) > i[data-on],
  .db-chart[data-variant="isotype"][data-force~="hover"] > .db-chart-plot > .db-chart-bar:not([data-shown]) > i[data-on] { background: var(--db-rule-strong); }
  .db-chart[data-variant="isotype"][data-moved] .db-chart-bar[data-shown] > i[data-on] { animation: db-chart-count var(--db-moderato) var(--db-spiccato) calc(var(--k) * var(--db-arpeggio)) both; }
  @keyframes db-chart-count { from { scale: 0.35; } to { scale: 1; } }
  .db-chart[data-variant="isotype"] > .db-chart-axis { margin-top: calc(-1 * var(--db-space-4)); }
  .db-chart-key { display: inline-flex; align-items: center; gap: var(--db-space-2); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-chart-key > i { inline-size: 0.5rem; aspect-ratio: 1; border-radius: 50%; background: var(--db-ink); }

  /* series: two or more read at once. Each has its own line, solid, dotted or dashed (a ring, a disc,
     a ring on the dots), and its own voice in the readout, roman, italic or pencil, as "It has to be
     design." pairs the two faces. Grouped, the stems stand side by side; stacked, one stem per column
     is cut into lengths with a dot at every joint, and the top joint is now's accent. */
  .db-chart-bar:has(> .db-chart-mark)::before, .db-chart-bar:has(> .db-chart-mark)::after { content: none; }
  .db-chart-mark { --c: var(--db-pencil); position: absolute; inset-block: 0; left: calc(50% + (var(--k) - (var(--m) - 1) / 2) * var(--db-space-2)); pointer-events: none; }
  .db-chart[data-stacked] .db-chart-mark { left: 50%; }
  .db-chart-mark::before, .db-chart-mark::after { content: ""; position: absolute; left: 0; }
  .db-chart-mark::before { bottom: calc(var(--b) * 100%); width: var(--db-hairline); height: calc((var(--v) - var(--b)) * 100%); translate: -50% 0; background: var(--c); }
  .db-chart-mark[data-series="1"]::before { background: repeating-linear-gradient(to top, var(--c) 0 1px, transparent 1px 3px); }
  .db-chart-mark[data-series="2"]::before { background: repeating-linear-gradient(to top, var(--c) 0 4px, transparent 4px 7px); }
  .db-chart-mark::after {
    z-index: 1; bottom: calc(var(--v) * 100%); width: 7px; height: 7px; border-radius: 50%; translate: -50% 50%;
    background: var(--db-paper); box-shadow: inset 0 0 0 var(--db-hairline) var(--c);
    transition: scale var(--db-moderato) var(--db-spiccato), background-color var(--db-allegro), box-shadow var(--db-allegro);
  }
  .db-chart-mark[data-series="1"]::after { background: var(--c); }
  .db-chart-bar:is(:hover, :focus-visible) > .db-chart-mark, .db-chart[data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown] > .db-chart-mark { --c: var(--db-ink); }
  .db-chart-bar:is(:hover, :focus-visible) > .db-chart-mark::after, .db-chart[data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown] > .db-chart-mark::after { scale: 1.5; }
  .db-chart:not([data-stacked]) .db-chart-bar[data-now] > .db-chart-mark[data-series="0"]::after,
  .db-chart[data-stacked] .db-chart-bar[data-now] > .db-chart-mark[data-top]::after { background: var(--db-accent); box-shadow: none; }

  /* The readout for several series: the one giant number becomes a short list, figures set flush
     right in a column as on a ledger, each rolling on its own; stacked, a rule and the sum under it. */
  .db-chart-read[data-list] { display: grid; row-gap: var(--db-space-3); }
  .db-chart-list { display: grid; grid-template-columns: max-content auto; column-gap: var(--db-space-4); row-gap: var(--db-space-1); align-items: baseline; justify-content: start; }
  .db-chart-row { display: contents; }
  .db-chart-row > .db-chart-value { grid-column: 1; }
  .db-chart-row > .db-chart-name { grid-column: 2; }
  .db-chart-list .db-chart-value { justify-self: end; font-size: clamp(var(--db-mf), 8cqi, var(--db-f)); letter-spacing: var(--db-f-tr); }
  .db-chart-row[data-total]::before { content: ""; grid-column: 1; border-top: var(--db-hairline) solid var(--db-ink); margin-block: var(--db-space-1) var(--db-space-2); }
  .db-chart-name { display: inline-flex; align-items: center; gap: var(--db-space-2); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-graphite); }
  .db-chart-row[data-series="1"] > .db-chart-name { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-pp) * var(--db-expression-scale)); }
  .db-chart-row[data-series="2"] > .db-chart-name { color: var(--db-pencil); }
  .db-chart-swatch { --c: var(--db-graphite); flex: none; inline-size: 1.5em; block-size: var(--db-hairline); background: var(--c); }
  .db-chart-row[data-series="1"] .db-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 3px); }
  .db-chart-row[data-series="2"] .db-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 4px, transparent 4px 7px); }
  .db-chart-row[data-total] .db-chart-swatch { visibility: hidden; }

  /* horizontal: a ledger. The names stand in a column at the start, each line runs out from a
     baseline on the start edge to its dot, and the name of the line the number reads is inked. */
  .db-chart[data-orientation="horizontal"] { grid-template-columns: max-content minmax(0, 1fr); column-gap: var(--db-space-4); }
  .db-chart[data-orientation="horizontal"] > .db-chart-read { grid-column: 1 / -1; }
  .db-chart[data-orientation="horizontal"] > :is(.db-chart-plot, .db-chart-axis) { grid-row: 2; grid-template-columns: none; grid-template-rows: repeat(var(--n, 12), var(--db-space-6)); }
  .db-chart[data-orientation="horizontal"] > .db-chart-plot {
    grid-column: 2; height: auto; box-shadow: none; border-inline-start: var(--db-hairline) solid var(--db-ink);
    background: repeating-linear-gradient(to right, var(--db-rule) 0 1px, transparent 1px 25%);
  }
  .db-chart[data-orientation="horizontal"] > .db-chart-axis { grid-column: 1; margin-top: 0; align-items: center; text-align: end; }
  .db-chart[data-orientation="horizontal"] > .db-chart-axis > [data-shown] { color: var(--db-ink); }
  .db-chart[data-orientation="horizontal"] .db-chart-bar::before { left: auto; bottom: auto; top: 50%; inset-inline-start: 0; width: calc(var(--v) * 100%); height: var(--db-hairline); translate: 0 -50%; }
  .db-chart[data-orientation="horizontal"] .db-chart-bar:is(:hover, :focus-visible)::before,
  .db-chart[data-orientation="horizontal"][data-force~="hover"] > .db-chart-plot > .db-chart-bar[data-shown]::before { width: calc(var(--v) * 100%); height: var(--db-stroke); }
  .db-chart[data-orientation="horizontal"] :is(.db-chart-bar, .db-chart-mark)::after { left: auto; bottom: auto; top: 50%; inset-inline-start: calc(var(--v) * 100%); margin-inline-start: -3.5px; translate: 0 -50%; }
  .db-chart[data-orientation="horizontal"] .db-chart-mark { inset: auto 0; top: calc(50% + (var(--k) - (var(--m) - 1) / 2) * var(--db-space-2)); height: 0; }
  .db-chart[data-orientation="horizontal"][data-stacked] .db-chart-mark { top: 50%; }
  .db-chart[data-orientation="horizontal"] .db-chart-mark::after { top: 0; }
  .db-chart[data-orientation="horizontal"] .db-chart-mark::before { left: auto; bottom: auto; top: 0; inset-inline-start: calc(var(--b) * 100%); width: calc((var(--v) - var(--b)) * 100%); height: var(--db-hairline); translate: 0 -50%; }
  .db-chart[data-orientation="horizontal"] .db-chart-mark[data-series="1"]::before { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 3px); }
  .db-chart[data-orientation="horizontal"] .db-chart-mark[data-series="2"]::before { background: repeating-linear-gradient(to right, var(--c) 0 4px, transparent 4px 7px); }

  @media (forced-colors: active) {
    .db-chart-bar::before, .db-chart[data-variant="isotype"] .db-chart-bar > i[data-on], .db-chart-key > i { background: CanvasText; forced-color-adjust: none; }
    .db-chart-bar[data-now]::after, .db-chart-bar[data-now] > .db-chart-mark:is([data-series="0"], [data-top])::after, .db-chart[data-variant="isotype"] .db-chart-bar[data-now] > i[data-top] { background: Highlight; forced-color-adjust: none; }
    .db-chart-mark, .db-chart-swatch { --c: CanvasText; forced-color-adjust: none; }
    .db-chart[data-variant="isotype"] .db-chart-bar > i { box-shadow: inset 0 0 0 1px CanvasText; forced-color-adjust: none; }
  }
}
